"use client";

import { useEffect, useRef, useState } from "react";
import { Volume2, VolumeX } from "lucide-react";

export default function Hero() {
  const [isMuted, setIsMuted] = useState(true);
  const videoRef = useRef<HTMLVideoElement>(null);
  const blurVideoRef = useRef<HTMLVideoElement>(null);

  const toggleMute = () => {
    if (videoRef.current) {
      videoRef.current.muted = !videoRef.current.muted;
      setIsMuted(videoRef.current.muted);
    }
    if (blurVideoRef.current) {
      blurVideoRef.current.muted = true; // Always keep background blur video muted
    }
  };

  return (
    <section
      id="home"
      className="relative h-screen w-full flex items-center justify-center overflow-hidden bg-black pt-32 pb-32 md:pt-0 md:pb-0"
    >
      {/* Video Backgrounds */}
      <div className="absolute inset-0 z-0 w-full h-full overflow-hidden">
        {/* Blurred Ambient Layer */}
        <video
          ref={blurVideoRef}
          src="/assets/mp_.mp4"
          autoPlay
          loop
          muted
          playsInline
          className="absolute inset-0 w-full h-full object-cover blur-3xl opacity-50 scale-110 pointer-events-none"
        />

        {/* Main Video Layer */}
        <video
          ref={videoRef}
          src="/assets/mp_.mp4"
          autoPlay
          loop
          muted
          playsInline
          className="absolute inset-0 w-full h-full object-cover opacity-100 transition-opacity duration-1000"
        />

        {/* Cinematic Dark Gradient Overlays */}
        <div className="absolute inset-0 bg-gradient-to-b from-black/80 via-black/40 to-background"></div>
        <div className="absolute inset-0 bg-gradient-to-r from-black/80 via-transparent to-black/80"></div>
      </div>

      {/* Tap for sound badge */}
      <button
        onClick={toggleMute}
        className="absolute bottom-10 left-1/2 -translate-x-1/2 z-50 flex items-center gap-2 px-4 py-2 bg-black/50 backdrop-blur-md border border-white/10 rounded-full text-white/80 hover:text-white hover:bg-black/70 transition-all cursor-pointer animate-bounce"
      >
        {isMuted ? <VolumeX size={20} /> : <Volume2 size={20} />}
        <span className="text-sm font-medium tracking-wide">
          {isMuted ? "Tap for sound" : "Muted"}
        </span>
      </button>

      {/* Spline Viewer (if used in Hero) */}
      <div className="absolute inset-0 z-10 w-full h-full flex items-center justify-center pointer-events-none">
        {/* We use standard HTML custom element provided by the global script in layout.tsx */}
        <spline-viewer
          url="https://prod.spline.design/Qx5d9lYyH-g7Q3eO/scene.splinecode"
          className="w-full h-full pointer-events-auto"
        ></spline-viewer>
      </div>

      {/* Geometric Decor */}
      <div className="absolute inset-0 z-0 pointer-events-none">
        <div className="absolute top-1/4 left-1/4 w-96 h-96 border border-indigo-500/10 rounded-full animate-pulse"></div>
        <div className="absolute bottom-1/4 right-1/4 w-[500px] h-[500px] border border-cyan-500/10 rounded-full animate-pulse delay-1000"></div>

        {/* Tech Pattern Accents */}
        <div className="absolute top-20 left-10 font-mono text-xs text-indigo-500/50 uppercase tracking-widest">
          [ HUD_STATUS: ACTIVE ]
        </div>
        <div className="absolute bottom-20 right-10 font-mono text-xs text-indigo-500/50 uppercase tracking-widest">
          [ SYS_MEM: OPTIMAL ]
        </div>
      </div>
    </section>
  );
}
